"""Render the dashboard from a data directory to plain ASCII text."""

from __future__ import annotations

from pathlib import Path

from . import parsers

WIDTH = 72


def _ascii(text: str) -> str:
    """Force a string to plain ASCII, replacing anything else with '?'."""
    return text.encode("ascii", errors="replace").decode("ascii")


def _heading(title: str) -> list[str]:
    return ["", title, "-" * len(title)]


def render_dashboard(data_dir: Path) -> str:
    """Load every input from *data_dir* and render the full dashboard."""
    manifest_r = parsers.parse_manifest(data_dir / "manifest.json")
    decisions_r = parsers.parse_decisions(data_dir / "decisions")
    questions_r = parsers.parse_open_questions(data_dir / "open-questions.md")
    tasks_r = parsers.parse_tasks(data_dir / "tasks.md")
    sources_r = parsers.parse_sources(data_dir / "sources.md")
    ingest_r = parsers.parse_ingest_log(data_dir / "ingest-log.jsonl")
    health_r = parsers.parse_health(data_dir / "health.json")

    data_warnings: list[str] = []
    for result in (manifest_r, decisions_r, questions_r, tasks_r,
                   sources_r, ingest_r, health_r):
        data_warnings.extend(result.warnings)

    manifest = manifest_r.value or {
        "project": "(unknown project)",
        "phase": "(unknown phase)",
        "source_of_truth": "",
        "providers": {},
    }
    decisions = decisions_r.value or []
    questions = questions_r.value or []
    tasks = tasks_r.value or []
    sources = sources_r.value or []
    ingest = ingest_r.value
    health = health_r.value or []

    lines: list[str] = []
    lines.append("=" * WIDTH)
    lines.append(f"PROJECT: {manifest['project']}")
    lines.append(f"PHASE:   {manifest['phase']}")
    lines.append("=" * WIDTH)

    # Source of truth -------------------------------------------------------
    lines += _heading("SOURCE OF TRUTH")
    if manifest["source_of_truth"]:
        lines.append(f"  {manifest['source_of_truth']}")
    else:
        lines.append("  (not set)")

    # Decisions --------------------------------------------------------------
    lines += _heading("CONFIRMED DECISIONS")
    confirmed = [d for d in decisions if d["status"] == "CONFIRMED"]
    other = [d for d in decisions if d["status"] != "CONFIRMED"]
    if confirmed:
        for decision in confirmed:
            lines.append(f"  [CONFIRMED] {decision['title']}")
    else:
        lines.append("  (none)")
    for decision in other:
        lines.append(f"  [{decision['status']}] {decision['title']}")

    # Open questions ---------------------------------------------------------
    open_qs = [q for q in questions if not q["closed"]]
    closed_qs = [q for q in questions if q["closed"]]
    lines += _heading(
        f"OPEN QUESTIONS ({len(open_qs)} open / {len(closed_qs)} closed)"
    )
    if questions:
        for question in questions:
            mark = "CLOSED" if question["closed"] else "OPEN  "
            lines.append(f"  [{mark}] {question['id']}: {question['title']}")
    else:
        lines.append("  (none)")

    # Research sources -------------------------------------------------------
    lines += _heading(f"RESEARCH SOURCES ({len(sources)})")
    if sources:
        for source in sources:
            lines.append(f"  - {source}")
    else:
        lines.append("  (none)")

    # Tasks ------------------------------------------------------------------
    done_tasks = [t for t in tasks if t["done"]]
    todo_tasks = [t for t in tasks if not t["done"]]
    lines += _heading(
        f"TASKS ({len(done_tasks)} done / {len(todo_tasks)} remaining)"
    )
    if tasks:
        for task in tasks:
            mark = "x" if task["done"] else " "
            lines.append(f"  [{mark}] {task['text']}")
    else:
        lines.append("  (none)")

    # Providers --------------------------------------------------------------
    providers = manifest["providers"]
    configured = {n: p for n, p in providers.items() if p["configured"]}
    missing_required = {n: p for n, p in providers.items()
                        if p["required"] and not p["configured"]}
    unconfigured = {n: p for n, p in providers.items() if not p["configured"]}

    lines += _heading("CONFIGURED PROVIDERS")
    if configured:
        for name, provider in configured.items():
            req = "required" if provider["required"] else "optional"
            detail = f" - {provider['detail']}" if provider["detail"] else ""
            lines.append(f"  {name} ({req}){detail}")
    else:
        lines.append("  (none)")

    lines += _heading("MISSING REQUIRED CONFIGURATION")
    if missing_required:
        for name, provider in missing_required.items():
            detail = f" - {provider['detail']}" if provider["detail"] else ""
            lines.append(f"  {name}{detail}")
    else:
        lines.append("  (none - all required providers configured)")

    # Last ingestion run -----------------------------------------------------
    lines += _heading("LAST INGESTION RUN")
    if ingest:
        lines.append(f"  captured:  {ingest.get('captured_utc') or '(unknown)'}")
        lines.append(f"  source:    {ingest.get('source') or '(unknown)'}")
        lines.append(f"  namespace: {ingest.get('namespace') or '(unknown)'}")
        chunks = ingest.get("chunks_stored")
        lines.append(f"  chunks:    {chunks if chunks is not None else '(unknown)'}")
    else:
        lines.append("  (no ingestion runs recorded)")

    # Next recommended actions ------------------------------------------------
    failed_checks = [c for c in health if not c["ok"]]
    actions: list[str] = []
    for question in open_qs:
        actions.append(f"Resolve {question['id']}: {question['title']}")
    for task in todo_tasks:
        actions.append(f"Complete task: {task['text']}")
    for check in failed_checks:
        actions.append(f"Fix health check '{check['name']}'"
                       f" ({check['severity']})")
    for name in missing_required:
        actions.append(f"Configure required provider: {name}")
    for name, provider in unconfigured.items():
        if not provider["required"]:
            actions.append(f"Consider configuring optional provider: {name}")

    lines += _heading("NEXT RECOMMENDED ACTIONS")
    if actions:
        for number, action in enumerate(actions, start=1):
            lines.append(f"  {number}. {action}")
    else:
        lines.append("  (nothing to do - all clear)")

    # Warnings -----------------------------------------------------------------
    lines += _heading("WARNINGS")
    warned = False
    for check in failed_checks:
        detail = f": {check['detail']}" if check["detail"] else ""
        lines.append(f"  [{check['severity'].upper()}] {check['name']}{detail}")
        warned = True
    for warning in data_warnings:
        lines.append(f"  [DATA] {warning}")
        warned = True
    if not warned:
        lines.append("  (none)")

    lines.append("")
    return _ascii("\n".join(lines))

